CREATE TABLE "BookingSubmission" ("userId" TEXT NOT NULL, "key" TEXT NOT NULL, "payloadHash" TEXT NOT NULL, "bookingIds" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("userId", "key"));
-- These guards cover court rentals AND private-course court assignments, including staff edits.
CREATE TRIGGER "Booking_no_overlap_insert" BEFORE INSERT ON "Booking"
WHEN NEW.courtId IS NOT NULL AND NEW.status IN ('pending','confirmed','CONFIRMED','PENDING_COACH_CONFIRMATION','AWAITING_PAYMENT')
BEGIN
 SELECT RAISE(ABORT, 'COURT_OVERLAP') WHERE EXISTS(SELECT 1 FROM "Booking" other WHERE other.id<>NEW.id AND other.courtId=NEW.courtId AND other.date=NEW.date AND other.status IN ('pending','confirmed','CONFIRMED','PENDING_COACH_CONFIRMATION','AWAITING_PAYMENT') AND ((CAST(substr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')-1)),1,instr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')-1)),':')-1) AS INTEGER)%12)*60 + CAST(substr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')-1)),instr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')-1)),':')+1,2) AS INTEGER) + CASE WHEN upper(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')-1))) LIKE '%PM' THEN 720 ELSE 0 END) < ((CAST(substr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')+1)),1,instr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')+1)),':')-1) AS INTEGER)%12)*60 + CAST(substr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')+1)),instr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')+1)),':')+1,2) AS INTEGER) + CASE WHEN upper(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')+1))) LIKE '%PM' THEN 720 ELSE 0 END) AND ((CAST(substr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')-1)),1,instr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')-1)),':')-1) AS INTEGER)%12)*60 + CAST(substr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')-1)),instr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')-1)),':')+1,2) AS INTEGER) + CASE WHEN upper(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')-1))) LIKE '%PM' THEN 720 ELSE 0 END) < ((CAST(substr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')+1)),1,instr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')+1)),':')-1) AS INTEGER)%12)*60 + CAST(substr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')+1)),instr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')+1)),':')+1,2) AS INTEGER) + CASE WHEN upper(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')+1))) LIKE '%PM' THEN 720 ELSE 0 END));
END;
CREATE TRIGGER "Booking_no_overlap_update" BEFORE UPDATE OF courtId,date,time,status ON "Booking"
WHEN NEW.courtId IS NOT NULL AND NEW.status IN ('pending','confirmed','CONFIRMED','PENDING_COACH_CONFIRMATION','AWAITING_PAYMENT')
BEGIN
 SELECT RAISE(ABORT, 'COURT_OVERLAP') WHERE EXISTS(SELECT 1 FROM "Booking" other WHERE other.id<>NEW.id AND other.courtId=NEW.courtId AND other.date=NEW.date AND other.status IN ('pending','confirmed','CONFIRMED','PENDING_COACH_CONFIRMATION','AWAITING_PAYMENT') AND ((CAST(substr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')-1)),1,instr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')-1)),':')-1) AS INTEGER)%12)*60 + CAST(substr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')-1)),instr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')-1)),':')+1,2) AS INTEGER) + CASE WHEN upper(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')-1))) LIKE '%PM' THEN 720 ELSE 0 END) < ((CAST(substr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')+1)),1,instr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')+1)),':')-1) AS INTEGER)%12)*60 + CAST(substr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')+1)),instr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')+1)),':')+1,2) AS INTEGER) + CASE WHEN upper(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')+1))) LIKE '%PM' THEN 720 ELSE 0 END) AND ((CAST(substr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')-1)),1,instr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')-1)),':')-1) AS INTEGER)%12)*60 + CAST(substr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')-1)),instr(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')-1)),':')+1,2) AS INTEGER) + CASE WHEN upper(trim(substr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),1,instr(replace(replace(replace(other.time,'–','—'),'-','—'),' to ','—'),'—')-1))) LIKE '%PM' THEN 720 ELSE 0 END) < ((CAST(substr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')+1)),1,instr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')+1)),':')-1) AS INTEGER)%12)*60 + CAST(substr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')+1)),instr(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')+1)),':')+1,2) AS INTEGER) + CASE WHEN upper(trim(substr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),instr(replace(replace(replace(NEW.time,'–','—'),'-','—'),' to ','—'),'—')+1))) LIKE '%PM' THEN 720 ELSE 0 END));
END;
